CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email text UNIQUE, phone text UNIQUE, password_hash text NOT NULL, name text NOT NULL, role text NOT NULL CHECK (role IN ('ADMIN','DESIGNER')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CHECK (email IS NOT NULL OR phone IS NOT NULL));
CREATE TABLE IF NOT EXISTS clients (id integer PRIMARY KEY, name text NOT NULL, email text, phone text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects (id integer PRIMARY KEY, name text NOT NULL, client_id integer NOT NULL REFERENCES clients(id), designer_id integer REFERENCES users(id), description text NOT NULL DEFAULT '', brief text NOT NULL DEFAULT '', priority text NOT NULL DEFAULT 'NORMAL' CHECK (priority IN ('LOW','NORMAL','HIGH')), due_date date, status text NOT NULL DEFAULT 'NEW' CHECK (status IN ('NEW','WAITING_FOR_DESIGNER','IN_DESIGN','WAITING_FOR_CLIENT','REVISION_REQUESTED','APPROVED','COMPLETED','CANCELLED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS portal_access (id bigserial PRIMARY KEY, client_id integer NOT NULL REFERENCES clients(id), project_id integer NOT NULL REFERENCES projects(id), code_hash text UNIQUE NOT NULL, expires_at timestamptz, revoked boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY, subject_type text NOT NULL CHECK (subject_type IN ('USER','CLIENT')), subject_id integer NOT NULL, project_id integer REFERENCES projects(id), role text NOT NULL CHECK (role IN ('ADMIN','DESIGNER','CLIENT')), name text NOT NULL, email text, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id bigserial PRIMARY KEY, project_id integer NOT NULL REFERENCES projects(id), sender_type text NOT NULL CHECK (sender_type IN ('ADMIN','DESIGNER','CLIENT')), sender_id integer, body text NOT NULL CHECK (length(body) BETWEEN 1 AND 5000), created_at timestamptz NOT NULL DEFAULT now(), client_event_id text);
CREATE UNIQUE INDEX IF NOT EXISTS messages_event_unique ON messages(project_id, sender_type, sender_id, client_event_id) WHERE client_event_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS versions (id bigserial PRIMARY KEY, project_id integer NOT NULL REFERENCES projects(id), number integer NOT NULL CHECK (number > 0), notes text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPROVED')), uploaded_by integer REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), approved_at timestamptz, UNIQUE(project_id, number));
CREATE TABLE IF NOT EXISTS revisions (id bigserial PRIMARY KEY, project_id integer NOT NULL REFERENCES projects(id), version_id bigint NOT NULL REFERENCES versions(id), client_id integer NOT NULL REFERENCES clients(id), request text NOT NULL CHECK (length(request) BETWEEN 3 AND 5000), status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','RESOLVED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS files (id bigserial PRIMARY KEY, project_id integer NOT NULL REFERENCES projects(id), message_id bigint REFERENCES messages(id), version_id bigint REFERENCES versions(id), uploaded_by_type text NOT NULL CHECK (uploaded_by_type IN ('ADMIN','DESIGNER','CLIENT')), uploaded_by_id integer, original_name text NOT NULL, stored_name text UNIQUE NOT NULL, mime text NOT NULL, size integer NOT NULL CHECK (size > 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS activity (id bigserial PRIMARY KEY, project_id integer NOT NULL REFERENCES projects(id), actor_type text NOT NULL, actor_id integer, action text NOT NULL, details text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id bigserial PRIMARY KEY, user_id integer NOT NULL REFERENCES users(id), project_id integer REFERENCES projects(id), title text NOT NULL, body text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS projects_status_idx ON projects(status); CREATE INDEX IF NOT EXISTS projects_designer_idx ON projects(designer_id); CREATE INDEX IF NOT EXISTS projects_client_idx ON projects(client_id); CREATE INDEX IF NOT EXISTS messages_project_idx ON messages(project_id,id); CREATE INDEX IF NOT EXISTS versions_project_idx ON versions(project_id,number); CREATE INDEX IF NOT EXISTS files_project_idx ON files(project_id); CREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(user_id,created_at DESC); CREATE INDEX IF NOT EXISTS activity_project_idx ON activity(project_id,created_at DESC); CREATE INDEX IF NOT EXISTS portal_code_idx ON portal_access(code_hash,revoked);
